#pragma once
static void crowfootTests(Window &w,const QString &output,std::function<void(QString,bool)> check){
 w.testMode=true;w.logicalView=false;w.uml=false;w.en=false;w.mode=1;w.model=Model::example();w.model.get("contiene")->identifying=false;w.selection.clear();w.selectionIds.clear();w.history.clear();w.applyTheme();w.buildMenus();
 auto feet=[&]{QVector<QGraphicsItem*> result;for(auto item:w.connectors)if(item->data(1)=="chenCrowFoot")result<<item;return result;};
 const QStringList cards={"0,1","1,1","0,N","1,N"};bool matrix=true,preserved=true,roles=true;
 for(const auto &ca:cards)for(const auto &cb:cards){auto r=w.model.get("contiene");r->cardA=ca;r->cardB=cb;const auto before=w.model.json();w.refresh();auto forks=feet();matrix&=forks.size()==int(ca.endsWith('N'))+int(cb.endsWith('N'));preserved&=w.model.json()==before;for(auto f:forks){roles&=f->data(0)=="contiene";roles&=f->data(2)=="A"?ca.endsWith('N'):cb.endsWith('N');}}
 check("Chen crow feet match all 16 min-max combinations without changing the model",matrix&&preserved&&roles);
 auto rel=w.model.get("contiene");rel->cardA="0,N";rel->cardB="1,N";w.refresh();
 bool labels=false;QStringList visible;for(auto i:w.connectors)if(auto text=dynamic_cast<QGraphicsSimpleTextItem*>(i))visible<<text->text();labels=visible.contains("(0,N)")&&visible.contains("(1,N)");check("Chen retains optional and mandatory min-max labels beside crow feet",labels);
 auto render=[&](const QString &name){w.selection.clear();w.selectionIds.clear();w.refresh();auto rect=w.scene->itemsBoundingRect().adjusted(-35,-35,35,35);QImage image((rect.size()*1.7).toSize(),QImage::Format_ARGB32_Premultiplied);image.fill(w.theme.paper);QPainter painter(&image);painter.setRenderHint(QPainter::Antialiasing);w.scene->render(&painter,QRectF(QPointF(0,0),image.size()),rect);painter.end();return image.save(output+"/"+name+".png");};
 check("Chen crow-foot image rendered",render("chen-zampe-NM"));
 bool orientation=true;for(const auto &point:{QPointF(700,220),QPointF(-300,220),QPointF(180,-300),QPointF(180,750),QPointF(800,800),QPointF(-600,-600)}){
  w.model.get("contiene")->chen=point;w.refresh();for(auto item:feet()){auto p=dynamic_cast<QGraphicsPathItem*>(item);orientation&=p&&p->path().elementCount()==6;if(!p)continue;auto node=w.nodes.value(item->data(2)=="A"?"ordine":"riga");QRectF rect(node->scenePos()-QPointF(node->size.width()/2,node->size.height()/2),node->size);for(int n=1;n<p->path().elementCount();n+=2){auto e=p->path().elementAt(n);orientation&=std::isfinite(e.x)&&std::isfinite(e.y)&&rect.adjusted(-.1,-.1,.1,.1).contains(QPointF(e.x,e.y))&&!rect.adjusted(.1,.1,-.1,-.1).contains(QPointF(e.x,e.y));}}
 }
 check("Crow-foot tips stay on entity borders in horizontal vertical and diagonal links",orientation);
 w.model=Model::example();w.refresh();check("Identifying association has one crow foot and retains identification",feet().size()==1&&w.nodes.value("contiene")->identifying&&w.model.get("contiene")->identifying);
 w.model.get("contiene")->chen={180,430};w.model.get("riga")->chen={180,680};w.model.get("numriga")->chen={0,830};w.model.get("quantita")->chen={350,830};w.refresh();check("Vertical Chen example rendered",render("chen-zampe-verticale"));
 w.model=Model::example();w.model.remove("riga");Object recursive;recursive.id="recursive";recursive.kind="relation";recursive.name="Collega";recursive.a=recursive.b="ordine";recursive.cardA="0,N";recursive.cardB="1,N";recursive.roleA="origine";recursive.roleB="destinazione";recursive.chen=recursive.uml={640,220};w.model.objects<<recursive;w.refresh();auto forks=feet();bool recursiveRoles=forks.size()==2;QSet<QString> endpoints;for(auto item:forks){endpoints<<item->data(2).toString();}check("Recursive relationship renders distinct A and B crow feet",recursiveRoles&&endpoints==QSet<QString>{"A","B"});check("Recursive Chen example rendered",render("chen-zampe-ricorsiva"));
 w.uml=true;w.refresh();check("UML multiplicities do not acquire Chen decorations",feet().isEmpty());
 w.uml=false;w.model=Model::example();w.model.get("contiene")->kind="isa";w.model.get("contiene")->a="riga";w.model.get("contiene")->b="ordine";w.refresh();check("ISA and attribute links do not acquire crow feet",feet().isEmpty());
 w.model=Model::example();w.mode=2;w.en=true;w.applyTheme();w.refresh();bool themed=!feet().isEmpty();for(auto item:feet()){auto p=dynamic_cast<QGraphicsPathItem*>(item);themed&=p&&p->pen().color()==w.theme.line&&item->toolTip().contains("Extended Chen");}check("Crow feet follow night colors and English help",themed);check("Night Chen example rendered",render("chen-zampe-notte"));
 QStringList errors;w.model.logical=generateLogical(w.model,{},errors).json();w.switchLevel(true);check("Logical model keeps its own FK notation",errors.isEmpty()&&feet().isEmpty());
 w.logicalView=false;w.uml=false;w.en=false;w.mode=1;w.model=Model::example();w.history.clear();w.selection.clear();w.selectionIds.clear();w.applyTheme();w.buildMenus();w.refresh();
}
